style.css:
/* Universal Stylish Font and Color Theme */

:root {
  --primary-color: #2a9d8f;       /* Main accent color */
  --secondary-color: #264653;     /* Darker accent */
  --background-color: #f0f4f8;    /* Light background */
  --text-color: #333333;          /* Default text color */
  --link-color: #e76f51;          /* Link color */
  --link-hover-color: #d65a3f;    /* Link hover color */
  --font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
}

body {
  font-family: var(--font-family);
  color: var(--text-color);
  background-color: var(--background-color);
  line-height: 1.6;
}

/* Headings use secondary color and slightly different font weight */
h1, h2, h3, h4, h5, h6 {
  color: var(--secondary-color);
  font-weight: 600;
  font-family: var(--font-family);
}

/* Links */
a {
  color: var(--link-color);
  text-decoration: none; /* keep links clean */
  transition: color 0.3s ease;
}

a:hover, a:focus {
  color: var(--link-hover-color);
  outline: none;
}

/* Buttons and inputs: change font and color, keep sizing intact */
button, input, select, textarea {
  font-family: var(--font-family);
  color: var(--text-color);
  background-color: transparent; /* keep original background */
  border-color: var(--primary-color);
}

